```json
{
  "root_causes": [
    {
      "service": "payment",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, attr_k8s_pod_name pod, min(time) first_seen, max(time) last_seen, count(*) n, min(value) min_uptime, max(value) max_uptime FROM abnormal_metrics_sum WHERE service_name='payment' AND metric='k8s.pod.uptime' GROUP BY 1,2 UNION ALL SELECT 'norm', attr_k8s_pod_name, min(time), max(time), count(*), min(value), max(value) FROM normal_metrics_sum WHERE service_name='payment' AND metric='k8s.pod.uptime' GROUP BY 1,2 ORDER BY 1,3",
          "claim": "Payment pod wx5b8 (uptime ~9541s) stops at 11:37:16; replacement pod 2f684 starts with uptime 2s at 11:37:17 and keeps running."
        },
        {
          "kind": "trace",
          "sql": "SELECT time, service_name, span_name, attr_span_kind, round(duration/1e6,1) ms, attr_status_code FROM abnormal_traces WHERE span_name LIKE '%PaymentService/Charge%' AND attr_span_kind='Client' AND service_name='checkout' AND attr_status_code='Error' ORDER BY time",
          "claim": "Checkout's PaymentService/Charge calls error after 1.8–20 s, during the payment pod swap window, with no payment server span."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='payment' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "Payment's own server spans stay fast (p95 about 1 ms) and show no errors; the failure is the pod swap, not slow processing."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "payment",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, count(*) n, round(avg(duration/1e6),1) ms, round(max(duration/1e6),1) mx FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_status_code='Error' AND attr_span_kind='Server') GROUP BY 1,2,3 ORDER BY n DESC",
          "claim": "Failed frontend-proxy requests contain checkout PlaceOrder and PaymentService/Charge client spans averaging about 5 s, up to 11 s."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name IN ('checkout','frontend') AND attr_span_kind='Server' GROUP BY 1,2,3 ORDER BY 1,2",
          "claim": "Checkout PlaceOrder server p95 rises to about 14.6 s with 4 errors; frontend server spans show 500s on its API routes."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, count(*) n, round(avg(duration/1e6),1) avg_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "frontend-proxy ingress returns 21 errors averaging about 730 ms in the abnormal window, against 12 errors in normal."
        }
      ]
    }
  ]
}
